"""Extreme heat hazard multipliers from NEX-GDDP-CMIP6 (MPI-ESM1-2-HR).

Event-day: tasmin above historical (1976-2005) 95th or 99th percentile. Variant: the heat index
filter is not applied (test of open question 2). HM = max(1, projected days / historical days).
"""

import numpy as np
import pandas as pd

from fri_rebuild import inputs

PERCENTILES = {"N95": 95, "N99": 99}


def event_days(scenario: str, period: str, thresholds: np.ndarray) -> np.ndarray:
    """Count of days per cell above the tasmin threshold."""
    tasmin = inputs.daily("tasmin", scenario, period)
    return (tasmin > thresholds).sum(axis=0).astype(float)


def county_mean(values: np.ndarray) -> np.ndarray:
    weights, _ = inputs.county_weights()
    totals = weights @ np.nan_to_num(values)
    return totals / np.asarray(weights.sum(axis=1)).ravel()


def hazard_multipliers() -> pd.DataFrame:
    """Columns EXHT_N95_<scenario>_HM and EXHT_N99_<scenario>_HM, indexed by county FIPS."""
    _, fips = inputs.county_weights()
    history = inputs.daily("tasmin", "historical", "historical")
    result = {}
    for name, percentile in PERCENTILES.items():
        thresholds = np.nanpercentile(history, percentile, axis=0)
        past_counts = (history > thresholds).sum(axis=0).astype(float)
        past = county_mean(past_counts)
        for warming, ssp in inputs.SSP.items():
            for period in ("MID", "LATE"):
                future = county_mean(event_days(ssp, period, thresholds))
                with np.errstate(divide="ignore", invalid="ignore"):
                    ratio = np.where(past > 0, future / past, np.nan)
                result[f"EXHT_{name}_{period}_{warming}_HM"] = np.maximum(1.0, ratio)
    return pd.DataFrame(result, index=fips)

"""Wildfire hazard multipliers from NEX-GDDP-CMIP6 Fire Weather Index and LANDFIRE fuels.

FRI Technical Documentation, Section 8: HM = (FWI_scenario / FWI_historic) ** gamma, where gamma
is the coefficient on log historic FWI in a log-log regression of NRI county EAL on FWI with
spatial fixed effects and fuel-type shares as controls.
"""

import numpy as np
import pandas as pd

from fri_rebuild import inputs

PERIODS = ("MID", "LATE")

FRI_HAZARD_EAL = ("CFLD_EALT", "HWAV_EALT", "HRCN_EALT", "RFLD_EALT", "WFIR_EALT")


def county_mean(values: np.ndarray) -> np.ndarray:
    weights, _ = inputs.county_weights()
    valid = np.isfinite(values)
    totals = weights @ np.where(valid, values, 0.0)
    covered = weights @ valid.astype(float)
    with np.errstate(invalid="ignore", divide="ignore"):
        return totals / covered


def period_fwi(scenario: str, period: str) -> np.ndarray:
    return county_mean(np.nanmean(inputs.fwi(scenario, period), axis=0))


def total_eal(baseline: pd.DataFrame) -> pd.Series:
    cols = [c for c in FRI_HAZARD_EAL if c in baseline.columns]
    if "WFIR_EALT" not in cols:
        return baseline["WFIR_EALT"]
    return baseline[cols].fillna(0.0).sum(axis=1)


def elasticity(historic_fwi: pd.Series) -> float:
    """gamma: OLS of ln(total EAL) on ln(FWI) and fuel shares, no spatial fixed effects."""
    baseline = inputs.baseline()
    fuels = inputs.county_fuel_shares().drop(columns="nonburnable")
    eal = total_eal(baseline)
    usable = (eal > 0) & (historic_fwi > 0) & fuels.notna().all(axis=1)
    design = pd.concat(
        [historic_fwi[usable].map(np.log).rename("log_fwi"), fuels[usable]], axis=1
    ).assign(const=1.0)
    coefficients, *_ = np.linalg.lstsq(
        design.to_numpy(), np.log(eal[usable].to_numpy()), rcond=None
    )
    return float(coefficients[0])


def hazard_multipliers() -> pd.DataFrame:
    """Columns WFIR_<period>_<warming>_HM indexed by county FIPS."""
    _, fips = inputs.county_weights()
    historic = pd.Series(period_fwi("historical", "historical"), index=fips)
    gamma = elasticity(historic)
    result = {}
    for warming, ssp in inputs.SSP.items():
        for period in PERIODS:
            future = pd.Series(period_fwi(ssp, period), index=fips)
            result[f"WFIR_{period}_{warming}_HM"] = (future / historic) ** gamma
    return pd.DataFrame(result, index=fips)

"""Coastal flooding hazard multipliers.

Primary route: 187 NOAA gauges, return-period frequency adjustment from extreme water level
curves shifted by relative sea level rise. Falls back to the HTF-decadal method on failure.
"""

import re

import geopandas as gpd
import numpy as np
import pandas as pd

from fri_rebuild import inputs

SEVERITIES = ("minor", "moderate", "major")
SCENARIOS = {"LOWER": "intermediate", "HIGHER": "high"}
DECADES = {"MID": 2050, "LATE": 2100}
CURRENT_DECADES = (2030,)
ANNUAL_CHANCE = pd.Series({"minor": 1.0, "moderate": 0.06, "major": 0.005})
SUB_RPS = {"minor": (1.0, 2.0), "moderate": (10.0, 20.0, 50.0), "major": (100.0,)}
MIN_RP = 0.1


def saturate(days):
    return 1.0 - np.exp(-days / 365.0)


def station_frequencies():
    tables = inputs.coastal_tables()
    projected = tables["htf_decadal"]
    base = projected[
        (projected["scenario"] == "intermediate") & (projected["decade"].isin(CURRENT_DECADES))
    ]
    current = base.pivot_table(index="station", columns="severity", values="days", aggfunc="mean")
    current = current.reindex(columns=list(SEVERITIES))
    return current, projected


def nearest_station(stations):
    counties = inputs.county_shapes()
    coastal = inputs.baseline()["CFLD_EALT"] > 0
    shapes = counties.loc[coastal[coastal].index].to_crs("EPSG:5070")
    shapes = shapes.copy()
    shapes["geometry"] = shapes.geometry.centroid
    points = inputs.points(stations).to_crs("EPSG:5070")
    joined = gpd.sjoin_nearest(shapes, points[["station", "geometry"]], how="left")
    return joined.groupby(level=0)["station"].first()


def htf_hm() -> pd.DataFrame:
    current_days, projected = station_frequencies()
    stations = projected.drop_duplicates("station")[["station", "lat", "lon"]]
    stations = stations[stations["station"].isin(current_days.index)]
    nearest = nearest_station(stations)
    current = saturate(current_days)[list(SEVERITIES)]
    weights = (current > 0).astype(float).mul(ANNUAL_CHANCE[list(SEVERITIES)], axis=1)
    total = weights.sum(axis=1)
    share = weights.div(total.where(total > 0), axis=0)
    result = {}
    for warming, scenario in SCENARIOS.items():
        for period, decade in DECADES.items():
            rows = projected[(projected["scenario"] == scenario) & (projected["decade"] == decade)]
            future_days = rows.pivot_table(index="station", columns="severity", values="days")
            future_days = future_days.reindex(index=current.index, columns=list(SEVERITIES))
            future = saturate(future_days)
            with np.errstate(divide="ignore", invalid="ignore"):
                factor = future / current.where(current > 0)
            station_hm = (factor.where(share > 0) * share).sum(axis=1, min_count=1)
            result[f"CFLD_{period}_{warming}_HM"] = nearest.map(station_hm)
    return pd.DataFrame(result)


def _return_period_table(ewl):
    meta = {"station", "id", "name", "state", "noaa_id", "stationid"}
    rp_cols = {}
    for c in ewl.columns:
        lc = str(c).lower()
        if lc in meta or "lat" in lc or "lon" in lc or "name" in lc or "state" in lc:
            continue
        if not pd.api.types.is_numeric_dtype(ewl[c]):
            continue
        m = re.search(r"\d+\.?\d*", str(c).replace("_", ".", 0))
        if not m:
            continue
        val = float(m.group(0))
        if val > 0:
            rp_cols[c] = val
    if len(rp_cols) < 4:
        raise ValueError("cannot parse return periods")
    order = sorted(rp_cols, key=lambda c: rp_cols[c])
    rps = np.array([rp_cols[c] for c in order], dtype=float)
    return order, rps


def _slr_table(slp, scenario):
    cols = {str(c).lower(): c for c in slp.columns}
    scen_col = next(c for k, c in cols.items() if "scen" in k)
    dec_col = cols.get("decade") or next(c for k, c in cols.items() if "year" in k or "decade" in k)
    d = slp.copy()
    for k, c in cols.items():
        if "percent" in k or k == "quantile":
            vals = d[c]
            if pd.api.types.is_numeric_dtype(vals):
                target = 50 if vals.max() > 1 else 0.5
                d = d[np.isclose(vals, target)]
            else:
                d = d[vals.astype(str).str.lower().str.contains("med|50")]
    d = d[d[scen_col].astype(str).str.lower().str.strip() == scenario]
    skip = {"station", dec_col, scen_col}
    cand = [
        c for c in d.columns
        if c not in skip and pd.api.types.is_numeric_dtype(d[c])
        and "lat" not in str(c).lower() and "lon" not in str(c).lower()
        and "percent" not in str(c).lower() and str(c).lower() != "quantile"
    ]
    pref = [c for c in cand if "med" in str(c).lower() or "50" in str(c).lower()]
    val_col = (pref or cand)[0]
    out = d.pivot_table(index="station", columns=dec_col, values=val_col, aggfunc="mean")
    return out, str(val_col).lower()


def ewl_hm() -> pd.DataFrame:
    tables = inputs.coastal_tables()
    ewl = tables["extreme_water_levels"].copy()
    slp = tables["sea_level_projections"].copy()
    ewl = ewl.drop_duplicates("station").set_index("station", drop=False)
    order, rps = _return_period_table(ewl)
    logrp = np.log(rps)

    # station coordinates
    if {"lat", "lon"}.issubset(ewl.columns):
        coords = ewl[["station", "lat", "lon"]]
    elif {"lat", "lon"}.issubset(slp.columns):
        coords = slp.drop_duplicates("station")[["station", "lat", "lon"]]
    else:
        coords = tables["htf_decadal"].drop_duplicates("station")[["station", "lat", "lon"]]
    weights = ANNUAL_CHANCE[list(SEVERITIES)]
    share = weights / weights.sum()

    result = {}
    per_scen = {}
    for warming, scenario in SCENARIOS.items():
        table, vname = _slr_table(slp, scenario)
        scale = 0.01 if "cm" in vname or table.abs().stack().max() > 30 else 1.0
        per_scen[warming] = table * scale

    st_hm = {}
    for warming in SCENARIOS:
        table = per_scen[warming]
        for period, decade in DECADES.items():
            col = decade if decade in table.columns else None
            if col is None:
                raise ValueError("decade missing")
            vals = {}
            for st in ewl.index:
                if st not in table.index or pd.isna(table.at[st, col]):
                    continue
                levels = ewl.loc[st, order].astype(float).values
                ok = ~np.isnan(levels)
                if ok.sum() < 4:
                    continue
                lv = np.maximum.accumulate(levels[ok])
                lr = logrp[ok]
                rise = float(table.at[st, col])
                hm = 0.0
                for sev in SEVERITIES:
                    fafs = []
                    for rp in SUB_RPS[sev]:
                        z = np.interp(np.log(rp), lr, lv)
                        new_level = z - rise
                        if new_level <= lv[0]:
                            rp_new = MIN_RP
                        else:
                            rp_new = float(np.exp(np.interp(new_level, lv, lr)))
                            rp_new = max(rp_new, MIN_RP)
                        fafs.append(rp / rp_new)
                    hm += share[sev] * float(np.mean(fafs))
                vals[st] = hm
            st_hm[f"CFLD_{period}_{warming}_HM"] = pd.Series(vals)

    stations = coords[coords["station"].isin(st_hm["CFLD_MID_LOWER_HM"].index)]
    stations = stations.dropna()
    nearest = nearest_station(stations)
    for k, s in st_hm.items():
        result[k] = nearest.map(s)
    out = pd.DataFrame(result)
    if out.notna().sum().min() < 50:
        raise ValueError("too few counties")
    return out


def hazard_multipliers() -> pd.DataFrame:
    """Columns CFLD_<period>_<warming>_HM indexed by county FIPS (coastal counties only)."""
    try:
        return ewl_hm()
    except Exception:
        return htf_hm()

"""Coastal flooding hazard multipliers.

Primary route: 187-gauge return-period frequency adjustment factors (extreme water levels plus
sea level rise). Fallback: NOAA high-tide-flooding projections at 110 gauges.
"""

import re

import geopandas as gpd
import numpy as np
import pandas as pd

from fri_rebuild import inputs

SEVERITIES = ("minor", "moderate", "major")
SCENARIOS = {"LOWER": "intermediate", "HIGHER": "high"}
DECADES = {"MID": 2050, "LATE": 2100}
CURRENT_DECADES = (2030,)
ANNUAL_CHANCE = pd.Series({"minor": 1.0, "moderate": 0.06, "major": 0.005})
OLD_RP = {"minor": 1.0, "moderate": 22.0, "major": 100.0}


def saturate(days):
    return 1.0 - np.exp(-days / 365.0)


def station_frequencies():
    tables = inputs.coastal_tables()
    projected = tables["htf_decadal"]
    base = projected[
        (projected["scenario"] == "intermediate") & (projected["decade"].isin(CURRENT_DECADES))
    ]
    current = base.pivot_table(index="station", columns="severity", values="days", aggfunc="mean")
    current = current.reindex(columns=list(SEVERITIES))
    return current, projected


def nearest_station(stations: pd.DataFrame) -> pd.Series:
    counties = inputs.county_shapes()
    coastal = inputs.baseline()["CFLD_EALT"] > 0
    shapes = counties.loc[coastal[coastal].index].to_crs("EPSG:5070")
    shapes = shapes.copy()
    shapes["geometry"] = shapes.geometry.centroid
    points = inputs.points(stations).to_crs("EPSG:5070")
    joined = gpd.sjoin_nearest(shapes, points[["station", "geometry"]], how="left")
    return joined.groupby(level=0)["station"].first()


def baseline_method() -> pd.DataFrame:
    current_days, projected = station_frequencies()
    stations = projected.drop_duplicates("station")[["station", "lat", "lon"]]
    stations = stations[stations["station"].isin(current_days.index)]
    nearest = nearest_station(stations)
    current = saturate(current_days)[list(SEVERITIES)]
    weights = (current > 0).astype(float).mul(ANNUAL_CHANCE[list(SEVERITIES)], axis=1)
    total = weights.sum(axis=1)
    share = weights.div(total.where(total > 0), axis=0)
    result = {}
    for warming, scenario in SCENARIOS.items():
        for period, decade in DECADES.items():
            rows = projected[(projected["scenario"] == scenario) & (projected["decade"] == decade)]
            future_days = rows.pivot_table(index="station", columns="severity", values="days")
            future_days = future_days.reindex(index=current.index, columns=list(SEVERITIES))
            future = saturate(future_days)
            with np.errstate(divide="ignore", invalid="ignore"):
                factor = future / current.where(current > 0)
            station_hm = (factor.where(share > 0) * share).sum(axis=1, min_count=1)
            result[f"CFLD_{period}_{warming}_HM"] = nearest.map(station_hm)
    return pd.DataFrame(result)


def rp_columns(df):
    out = {}
    for c in df.columns:
        if c in ("station", "lat", "lon", "name", "state"):
            continue
        m = re.findall(r"\d+\.?\d*", str(c))
        if not m:
            continue
        if not pd.api.types.is_numeric_dtype(df[c]):
            continue
        out[c] = float(m[0])
    return out


def return_period_hm() -> pd.DataFrame:
    tables = inputs.coastal_tables()
    ewl = tables["extreme_water_levels"].copy()
    slr = tables["sea_level_projections"].copy()
    if "station" not in ewl.columns:
        ewl = ewl.reset_index()
    rpc = rp_columns(ewl)
    cols = sorted(rpc, key=lambda c: rpc[c])
    rps = np.array([rpc[c] for c in cols])
    ewl = ewl.drop_duplicates("station").set_index("station")
    levels = ewl[cols].astype(float)
    levels = levels[levels.notna().sum(axis=1) >= 3]
    # sea level rise table: find value column
    if "station" not in slr.columns:
        slr = slr.reset_index()
    skip = {"station", "lat", "lon", "decade", "year"}
    pcol = [c for c in slr.columns if str(c).lower() in ("percentile", "quantile", "pct")]
    if pcol:
        pc = pcol[0]
        vals = slr[pc]
        med = vals.iloc[(vals - 50).abs().argsort()[:1]].iloc[0] if vals.max() > 1 else 0.5
        slr = slr[np.isclose(vals, med)]
    num = [c for c in slr.columns if pd.api.types.is_numeric_dtype(slr[c]) and c not in skip and c not in pcol]
    vcol = [c for c in num if re.search(r"cm|rise|rsl|slr|value|level", str(c).lower())]
    vcol = (vcol or num)[-1]
    dcol = "decade" if "decade" in slr.columns else "year"
    scol = "scenario"
    slr[scol] = slr[scol].astype(str).str.lower().str.replace(" ", "-").str.replace("_", "-")
    scen_names = {"intermediate": "intermediate", "high": "high"}
    stations_all = ewl.loc[levels.index]
    pts = stations_all[["lat", "lon"]].reset_index() if "lat" in stations_all.columns else None
    if pts is None:
        proj = tables["htf_decadal"].drop_duplicates("station")[["station", "lat", "lon"]]
        pts = proj[proj["station"].isin(levels.index)]
    nearest = nearest_station(pts[["station", "lat", "lon"]])
    logrp = np.log(rps)
    zmap = {"minor": 1.0, "moderate": 22.0, "major": 100.0}

    def level_at(row, rp):
        v = row.values.astype(float)
        ok = ~np.isnan(v)
        return np.interp(np.log(rp), logrp[ok], v[ok])

    def rp_at(row, z):
        v = row.values.astype(float)
        ok = ~np.isnan(v)
        v, lr = v[ok], logrp[ok]
        if z <= v[0]:
            return float(np.exp(lr[0]))
        if z >= v[-1]:
            slope = (lr[-1] - lr[-2]) / max(v[-1] - v[-2], 1e-6)
            return float(np.exp(lr[-1] + slope * (z - v[-1])))
        return float(np.exp(np.interp(z, v, lr)))

    weights = ANNUAL_CHANCE[list(SEVERITIES)]
    share = weights / weights.sum()
    result = {}
    for warming, scenario in SCENARIOS.items():
        for period, decade in DECADES.items():
            sub = slr[(slr[scol] == scenario) & (slr[dcol] == decade)]
            sub = sub.groupby("station")[vcol].mean()
            rise_scale = 0.01
            hm = {}
            for st in levels.index:
                if st not in sub.index or pd.isna(sub[st]):
                    continue
                rise = sub[st] * rise_scale
                row = levels.loc[st]
                total = 0.0
                for sev in SEVERITIES:
                    z = level_at(row, zmap[sev])
                    new_rp = rp_at(row, z - rise)
                    new_rp = max(new_rp, 0.1)
                    total += share[sev] * OLD_RP[sev] / new_rp
                hm[st] = total
            result[f"CFLD_{period}_{warming}_HM"] = nearest.map(pd.Series(hm))
    return pd.DataFrame(result)


def hazard_multipliers() -> pd.DataFrame:
    try:
        out = return_period_hm()
        if out.notna().sum().min() < 20 or not np.isfinite(out.values.astype(float)[~np.isnan(out.values.astype(float))]).all():
            raise ValueError("insufficient coverage")
        return out
    except Exception:
        return baseline_method()

"""Coastal flooding hazard multipliers from NOAA extreme water level curves + sea level rise.

FRI Technical Documentation, Section 4: each county takes the projected minor, moderate and
major flooding frequencies of its nearest tide gauge (187 gauges). Sub-types are defined by
return period (minor 1-2 yr, moderate 10-50 yr, major 100 yr). For each gauge and sub-type the
frequency adjustment factor is the exceedance rate of today's flood level after raising mean sea
level by the scenario's relative rise, divided by today's rate. HM = sum SubFAF x SubProportion.
"""

import re

import geopandas as gpd
import numpy as np
import pandas as pd

from fri_rebuild import inputs

SEVERITIES = ("minor", "moderate", "major")
SCENARIOS = {"LOWER": 1.0, "HIGHER": 2.0}  # GMSL by 2100 in metres (Intermediate, High)
YEARS = {"MID": 2050, "LATE": 2100}
RETURN_PERIODS = {
    "minor": [1.0, 1.5, 2.0],
    "moderate": [10.0, 15.0, 20.0, 25.0, 30.0, 35.0, 40.0, 45.0, 50.0],
    "major": [100.0],
}
ANNUAL_CHANCE = {"minor": 1.0, "moderate": 0.06, "major": 0.005}
MAX_RATE = 10.0  # events per year (table's shortest return period is 0.1 yr)


def return_level_curves() -> dict:
    """Per gauge: (return periods, levels in m above MHHW) from the extreme water level table."""
    ewl = inputs.coastal_tables()["extreme_water_levels"]
    cols = {}
    for c in ewl.columns:
        m = re.match(r"^([0-9.]+)yrRL", str(c))
        if m:
            cols[c] = float(m.group(1))
    ordered = sorted(cols, key=lambda c: cols[c])
    rps = np.array([cols[c] for c in ordered])
    curves = {}
    for _, row in ewl.iterrows():
        lv = row[ordered].to_numpy(dtype=float)
        ok = np.isfinite(lv)
        if ok.sum() < 5:
            continue
        lv = np.maximum.accumulate(lv[ok])
        curves[int(row["St"])] = (rps[ok], lv, float(row["Latitude"]), float(row["Longitude"]))
    return curves


def log_rate(level, rps, lv):
    """Log annual exceedance rate at a level; capped at MAX_RATE, extrapolated above the table."""
    lr = -np.log(rps)
    if level <= lv[0]:
        return np.log(MAX_RATE)
    if level <= lv[-1]:
        return min(np.interp(level, lv, lr), np.log(MAX_RATE))
    i = max(len(lv) - 2, 0)
    j = np.searchsorted(rps, 50.0)
    j = min(j, len(lv) - 2)
    i = j
    dl = max(lv[-1] - lv[i], 1e-6)
    slope = (lr[-1] - lr[i]) / dl
    return lr[-1] + slope * (level - lv[-1])


def parse_scenarios(slr: pd.DataFrame) -> pd.DataFrame:
    pat = re.compile(r"^\s*([0-9.]+)\s*-\s*([A-Za-z]+)")
    meters, kinds = [], []
    for s in slr["Scenario"].astype(str):
        m = pat.match(s)
        meters.append(float(m.group(1)) if m else np.nan)
        kinds.append(m.group(2).upper() if m else "")
    out = slr.copy()
    out["gmsl_m"] = meters
    out["kind"] = kinds
    return out


def station_rises(curves: dict) -> dict:
    """Relative sea level rise (m) per gauge, scenario and period (median projections)."""
    slr = parse_scenarios(inputs.coastal_tables()["sea_level_projections"])
    slr = slr[slr["NOAA ID"].notna() & slr["Lat"].notna() & slr["Long"].notna()]
    slr = slr[slr["kind"] == "MED"]
    rises = {}
    for warming, gm in SCENARIOS.items():
        sub = slr[np.isclose(slr["gmsl_m"], gm)]
        ids = sub["NOAA ID"].astype(float).astype(int).to_numpy()
        lat = sub["Lat"].to_numpy(dtype=float)
        lon = sub["Long"].to_numpy(dtype=float)
        for st, (_, _, la, lo) in curves.items():
            hit = np.where(ids == st)[0]
            if len(hit):
                k = hit[0]
            else:
                d = (lat - la) ** 2 + ((lon - lo) * np.cos(np.radians(la))) ** 2
                k = int(np.argmin(d))
            for period, year in YEARS.items():
                rises[(st, warming, period)] = float(sub.iloc[k][f"RSL{year}"]) / 100.0
    return rises


def nearest_station(stations: pd.DataFrame) -> pd.Series:
    counties = inputs.county_shapes()
    coastal = inputs.baseline()["CFLD_EALT"] > 0
    shapes = counties.loc[coastal[coastal].index].to_crs("EPSG:5070")
    shapes = shapes.copy()
    shapes["geometry"] = shapes.geometry.centroid
    points = inputs.points(stations).to_crs("EPSG:5070")
    joined = gpd.sjoin_nearest(shapes, points[["station", "geometry"]], how="left")
    return joined.groupby(level=0)["station"].first()


def hazard_multipliers() -> pd.DataFrame:
    """Columns CFLD_<period>_<warming>_HM indexed by county FIPS (coastal counties only)."""
    curves = return_level_curves()
    rises = station_rises(curves)
    stations = pd.DataFrame(
        [{"station": st, "lat": v[2], "lon": v[3]} for st, v in curves.items()]
    )
    nearest = nearest_station(stations)
    total = sum(ANNUAL_CHANCE.values())
    share = {s: ANNUAL_CHANCE[s] / total for s in SEVERITIES}
    result = {}
    for warming in SCENARIOS:
        for period in YEARS:
            hm = {}
            for st, (rps, lv, _, _) in curves.items():
                rise = rises[(st, warming, period)]
                total_hm = 0.0
                for sev in SEVERITIES:
                    fafs = []
                    for rp in RETURN_PERIODS[sev]:
                        z = float(np.interp(rp, rps, lv))
                        old = -np.log(rp)
                        new = log_rate(z - rise, rps, lv)
                        fafs.append(np.exp(new - old))
                    total_hm += share[sev] * float(np.mean(fafs))
                hm[st] = total_hm
            result[f"CFLD_{period}_{warming}_HM"] = nearest.map(pd.Series(hm))
    return pd.DataFrame(result)

"""Coastal flooding hazard multipliers from NOAA extreme water levels and sea level rise.

FRI Technical Documentation, Section 4: each county takes the flood-frequency change of its
nearest of 187 NOAA tide gauges. Sub-types are defined by return period (minor 1-2 yr, moderate
10-50 yr, major 100 yr). For each gauge and sub-type, today's flood level z is read from the
return-level curve; the scenario's relative sea level rise r shifts the curve, so z has the return
period of the level z - r today. FAF = old return period / new return period. HM = sum over
sub-types of FAF x SubProportion.
"""

import geopandas as gpd
import numpy as np
import pandas as pd

from fri_rebuild import inputs

SCENARIOS = {"LOWER": "1.0 - MED", "HIGHER": "2.0 - MED"}
YEARS = {"MID": 2050, "LATE": 2100}
SUBTYPES = {"minor": (1, 2), "moderate": (10, 20, 30, 40, 50), "major": (100,)}
MIN_RP = 0.1


def return_levels() -> pd.DataFrame:
    """Return levels (m above MHHW), indexed by gauge, columns = return period in years."""
    table = inputs.coastal_tables()["extreme_water_levels"].set_index("St")
    levels = table.filter(regex=r"^\d+(\.\d+)?yrRL")
    levels.columns = [float(c.split("yr")[0]) for c in levels.columns]
    return levels.dropna(how="any")


def sea_level_rise(gauges: pd.DataFrame) -> pd.DataFrame:
    """Relative rise since 2000 (m) per gauge, scenario and period (NOAA ID, else nearest site)."""
    slr = inputs.coastal_tables()["sea_level_projections"]
    slr = slr[slr["Lat"].notna() | slr["NOAA ID"].notna()]
    out = {}
    for warming, label in SCENARIOS.items():
        rows = slr[slr["Scenario"] == label].dropna(subset=["Lat"])
        by_id = rows[rows["NOAA ID"].notna()].drop_duplicates("NOAA ID").set_index("NOAA ID")
        sites = rows.reset_index(drop=True)
        for period, year in YEARS.items():
            rise = (sites[f"RSL{year} (cm)"]) / 100.0
            values = {}
            for gauge, row in gauges.iterrows():
                if float(gauge) in by_id.index:
                    site = by_id.loc[float(gauge)]
                    values[gauge] = (site[f"RSL{year} (cm)"]) / 100
                else:
                    d = (sites["Lat"] - row["Latitude"]) ** 2 + (
                        (sites["Long"] - row["Longitude"]) * np.cos(np.radians(row["Latitude"]))
                    ) ** 2
                    values[gauge] = rise.iloc[int(d.values.argmin())]
            out[f"{period}_{warming}"] = pd.Series(values)
    return pd.DataFrame(out)


def new_return_period(levels: np.ndarray, rps: np.ndarray, z: float) -> float:
    """Return period whose level is z (log-linear interpolation, capped at the table's range)."""
    if z <= levels[0]:
        return rps[0]
    if z >= levels[-1]:
        slope = (np.log(rps[-1]) - np.log(rps[-6])) / (levels[-1] - levels[-6])
        return float(np.exp(np.log(rps[-1]) + slope * (z - levels[-1])))
    return float(np.exp(np.interp(z, levels, np.log(rps))))


def gauge_hm() -> pd.DataFrame:
    levels = return_levels()
    meta = inputs.coastal_tables()["extreme_water_levels"].set_index("St").loc[levels.index]
    rise = sea_level_rise(meta[["Latitude", "Longitude"]])
    rps = np.array(levels.columns, dtype=float)
    freq = pd.Series({k: np.mean(1 / np.array(v, dtype=float)) for k, v in SUBTYPES.items()})
    share = freq / freq.sum()
    result = {}
    for col in rise.columns:
        hm = {}
        for gauge in levels.index:
            curve = np.maximum.accumulate(levels.loc[gauge].values)
            total = 0.0
            for sub, periods in SUBTYPES.items():
                old = np.array(periods, dtype=float)
                z = np.interp(np.log(old), np.log(rps), curve)
                new = np.array([new_return_period(curve, rps, zi - rise.loc[gauge, col]) for zi in z])
                faf = (1 / new).sum() / (1 / old).sum()
                total += faf * share[sub]
            hm[gauge] = total
        result[f"CFLD_{col.split('_')[0]}_{col.split('_')[1]}_HM"] = pd.Series(hm)
    return pd.DataFrame(result), meta


def nearest_gauge(gauges: pd.DataFrame) -> pd.Series:
    counties = inputs.county_shapes()
    coastal = inputs.baseline()["CFLD_EALT"] > 0
    shapes = counties.loc[coastal[coastal].index].to_crs("EPSG:5070")
    stations = gauges.reset_index().rename(columns={"St": "station", "Latitude": "lat", "Longitude": "lon"})
    points = inputs.points(stations).to_crs("EPSG:5070")
    joined = gpd.sjoin_nearest(shapes, points[["station", "geometry"]], how="left")
    return joined.groupby(level=0)["station"].first()


def hazard_multipliers() -> pd.DataFrame:
    """Columns CFLD_<period>_<warming>_HM indexed by county FIPS (coastal counties only)."""
    station_hm, meta = gauge_hm()
    nearest = nearest_gauge(meta[["Latitude", "Longitude"]])
    return pd.DataFrame({c: nearest.map(station_hm[c]) for c in station_hm.columns})

"""Wildfire hazard multipliers from NEX-GDDP-CMIP6 Fire Weather Index and LANDFIRE fuels.

FRI Technical Documentation, Section 8: HM = (FWI_scenario / FWI_historic) ** gamma, where gamma
is the coefficient on log historic FWI in a log-log regression of NRI county EAL on FWI with
spatial fixed effects and fuel-type shares as controls.
"""

import numpy as np
import pandas as pd

from fri_rebuild import inputs

PERIODS = ("MID", "LATE")


def county_mean(values: np.ndarray) -> np.ndarray:
    weights, _ = inputs.county_weights()
    valid = np.isfinite(values)
    totals = weights @ np.where(valid, values, 0.0)
    covered = weights @ valid.astype(float)
    with np.errstate(invalid="ignore", divide="ignore"):
        return totals / covered


def cell_fwi(scenario: str, period: str) -> np.ndarray:
    return np.nanmean(inputs.fwi(scenario, period, "FWI_P75", ensemble="MME75"), axis=0)


def period_fwi(scenario: str, period: str) -> np.ndarray:
    return county_mean(cell_fwi(scenario, period))


def elasticity(historic_fwi: pd.Series) -> float:
    """gamma: OLS of ln(wildfire EAL) on ln(FWI), fuel shares and state fixed effects."""
    baseline = inputs.baseline()
    fuels = inputs.county_fuel_shares().drop(columns="nonburnable")
    eal = baseline["WFIR_EALT"]
    usable = (eal > 0) & (historic_fwi > 0) & fuels.notna().all(axis=1)
    states = pd.get_dummies(baseline.loc[usable, "STATEABBRV"], drop_first=True, dtype=float)
    design = pd.concat(
        [historic_fwi[usable].map(np.log).rename("log_fwi"), fuels[usable], states], axis=1
    ).assign(const=1.0)
    coefficients, *_ = np.linalg.lstsq(
        design.to_numpy(), np.log(eal[usable].to_numpy()), rcond=None
    )
    return float(coefficients[0])


def hazard_multipliers() -> pd.DataFrame:
    """Columns WFIR_<period>_<warming>_HM indexed by county FIPS."""
    _, fips = inputs.county_weights()
    historic = pd.Series(period_fwi("historical", "historical"), index=fips)
    gamma = elasticity(historic)
    result = {}
    for warming, ssp in inputs.SSP.items():
        for period in PERIODS:
            ratio = cell_fwi(ssp, period) / cell_fwi("historical", "historical")
            ratio = np.where(np.isfinite(ratio) & (ratio > 0), ratio, np.nan)
            result[f"WFIR_{period}_{warming}_HM"] = county_mean(ratio**gamma)
    return pd.DataFrame(result, index=fips)

"""agent3 recipe: NOAA flood thresholds x extreme water level curve x sea level rise.

Sub-type current frequency = annual exceedance frequency of the NOAA minor/moderate/major
threshold (m above MHHW) read from the gauge's return-level curve (log-linear beyond the table).
Future frequency = same at (threshold - median relative SLR), capped at CAP events/year.
SLR taken from the nearest projection grid cell to the gauge (by lat/lon).
"""

import numpy as np

from fri_rebuild.coastal import forensics
from fri_rebuild.sources import tide_gauges as coastal

SCEN = ["1.0 - MED", "2.0 - MED"]  # LOWER, HIGHER scenario labels
CAP = 10.0  # events per year (0.1-year return period, shortest in the table)
USE_ID = True  # use the NOAA-ID matched projection when the gauge has one
EXN = 6
SHIFT = 0.0  # metres added to the threshold for the current frequency
SHIFT_FUT = 0.06  # metres: EMPIRICAL global offset (rise effectively 6 cm smaller); meaning unknown, fitted to FEMA values
STEP = None  # None, floor, ceil, near: read the return period off a table row instead of interpolating
CLAMP_TOP = False
FILL = "nearest"  # None, "median" or "nearest": gauges without NOAA thresholds get the median threshold across gauges
INTERP = "logrp"  # interpolation between table points: logrp, rp, freq
LOW_EXTRAP = True  # extrapolate log-linearly below the 0.1-year level, then cap
OFFSETS = ()
RISE_SCALE = 1.0  # multiplier on the rise
Y_MID = 2050  # year of the mid-century projection
Y_LATE = 2100
ADD_MID = 0.0  # cm added to the 2050 rise
ADD_LATE = 0.0  # cm added to the 2100 rise
BASE = None
_cache = {}


def _setup():
    if _cache:
        return _cache
    t = coastal.tables()
    _cache["t"] = t
    _cache["cols"], _cache["per"] = forensics.return_periods(t["extreme_water_levels"])
    return _cache


def _rises(row, t):
    s = t["sea_level_projections"]
    lat, lon = row.Latitude, row.Longitude
    if USE_ID:
        m = s[s["NOAA ID"] == float(row.St)]
        if not m.empty:
            lat, lon = m.iloc[0].Lat, m.iloc[0].Long
    c = np.cos(np.radians(lat))
    d = (s.Lat - lat) ** 2 + np.minimum(((s.Long - lon) * c) ** 2, ((s.Long - lon - 360) * c) ** 2)
    i = d.idxmin()
    r = s[(s.Lat == s.loc[i, "Lat"]) & (s.Long == s.loc[i, "Long"])].set_index("Scenario")
    out = []
    for sc in SCEN:
        pass
    vals = {}
    for sc in SCEN:
        for y in (2050, 2100):
            yy = Y_MID if y == 2050 else Y_LATE
            xs = np.arange(2020, 2151, 10)
            ys = [r.loc[sc, f"RSL{x} (cm)"] for x in xs]
            v = float(np.interp(yy, xs, ys)) / 100
            if OFFSETS:
                v += sum(r.loc[sc, c] for c in OFFSETS) / 100
            v += (ADD_MID if y == 2050 else ADD_LATE) / 100
            if BASE:
                v -= r.loc[sc, BASE] / 100
            vals[(sc, y)] = v * RISE_SCALE
    return vals


def freq(z, lv, per):
    if STEP:
        if z <= lv[0] and STEP != "ceil":
            return CAP
        if z >= lv[-1]:
            if CLAMP_TOP:
                return 1 / per[-1]
        else:
            if STEP == "floor":
                j = np.searchsorted(lv, z, side="right") - 1
            elif STEP == "ceil":
                j = np.searchsorted(lv, z, side="left")
            else:
                j = int(np.argmin(np.abs(lv - z)))
            return min(CAP, 1 / per[max(j, 0)])
    if z <= lv[0]:
        if not LOW_EXTRAP:
            return CAP
        sl = (np.log(per[1]) - np.log(per[0])) / (lv[1] - lv[0])
        return min(CAP, float(np.exp(-(np.log(per[0]) + sl * (z - lv[0])))))
    if z >= lv[-1]:
        sl = (np.log(per[-1]) - np.log(per[-EXN])) / (lv[-1] - lv[-EXN])
        return min(CAP, float(np.exp(-(np.log(per[-1]) + sl * (z - lv[-1])))))
    if INTERP == "logrp":
        return min(CAP, float(np.exp(-np.interp(z, lv, np.log(per)))))
    if INTERP == "rp":
        return min(CAP, float(1 / np.interp(z, lv, per)))
    return min(CAP, float(np.interp(z, lv, 1 / per)))


def gauge_factors(gauge):
    c = _setup()
    t, cols, per = c["t"], c["cols"], c["per"]
    e = t["extreme_water_levels"]
    row = e[e.St.astype(str) == gauge]
    th = t["flood_thresholds"]
    th = th[th.station.astype(str) == gauge]
    if row.empty or th.empty:
        return None
    T = th.iloc[0, 1:].to_numpy(float)
    if np.isnan(T).any():
        if not FILL:
            return None
        allT = t["flood_thresholds"].iloc[:, 1:].to_numpy(float)
        if FILL == "median":
            T = np.nanmedian(allT, axis=0)
        else:  # nearest gauge (by lat/lon) that has NOAA thresholds
            have = t["flood_thresholds"].dropna()
            ids = set(have.station.astype(str))
            e2 = e[e.St.astype(str).isin(ids)]
            c = np.cos(np.radians(row.iloc[0].Latitude))
            d = (e2.Latitude - row.iloc[0].Latitude) ** 2 + ((e2.Longitude - row.iloc[0].Longitude) * c) ** 2
            nid = str(e2.loc[d.idxmin(), "St"])
            T = have[have.station.astype(str) == nid].iloc[0, 1:].to_numpy(float)
    row = row.iloc[0]
    lv = np.maximum.accumulate(row[cols].to_numpy(float))
    r = _rises(row, t)
    out = []
    for z in T:
        p0 = freq(z + SHIFT, lv, per)
        z = z + SHIFT_FUT
        out.append(
            [
                freq(z - r[(SCEN[0], 2050)], lv, per) / p0,
                freq(z - r[(SCEN[1], 2050)], lv, per) / p0,
                freq(z - r[(SCEN[0], 2100)], lv, per) / p0,
                freq(z - r[(SCEN[1], 2100)], lv, per) / p0,
            ]
        )
    return np.array(out)
